local mainMod = "SUPER"

local touchpad_name = "crq1080:00-0488:1014-touchpad"
local touchpad_enabled = true

hl.bind(mainMod .. "+ T", function()
    touchpad_enabled = not touchpad_enabled
    hl.device({
        name = touchpad_name,
        enabled = touchpad_enabled
    })
    -- Optional desktop notification:
    hl.dsp.exec_cmd(string.format("notify-send -t 1000 'Touchpad' '%s'", touchpad_enabled and "Enabled" or "Disabled"))
end)


