hl.on("hyprland.start", function()
    hl.exec_cmd("waybar & nm-applet --indicator")
    hl.exec_cmd("rm \"$HOME/.cache/cliphist/db\"")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("awww-daemon")
    hl.exec_cmd("/usr/bin/gnome-keyring-daemon --start --components=secrets")
    hl.exec_cmd("env GDK_BACKEND=x11 gsr-ui")
    
    -- Launch loop script as a non-blocking background task
    hl.exec_cmd("bash -c 'while true; do ~/.config/hypr/touchpad-auto.sh; sleep 2; done' &")
end)
